function sentenceContext(value, startIndex) {
  const text = String(value || '');
  let start = Math.max(text.lastIndexOf('.', startIndex), text.lastIndexOf('\n', startIndex), text.lastIndexOf('!', startIndex), text.lastIndexOf('?', startIndex));
